komponenten-feedback-snackbar--interakti.snippet:
import { Component } from '@angular/core';
import { SnackbarComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [SnackbarComponent],
  template: `
    <cds-snackbar
        [message]="'Formular gespeichert, noch nicht abgesendet.'"
        [tone]="'def'"
        [actionLabel]="'Jetzt senden'"
        (action)="action($event)"
    />`,
})
export class DemoComponent {
  action(event: unknown) {}
}

